{
  "story": "How can a sender encrypt a message without sharing a secret first? Start with readable text, encrypt with the receiver’s public key, then compare decryption attempts. Only the matching private key recovers the message. Assume secure encryption and an uncompromised private key; ciphertext is schematic.",
  "aha": {
    "stateId": "private-decrypt",
    "observation": "Sharing the public key enables encryption without enabling feasible decryption; the matching private key recovers the original message."
  },
  "layout": {
    "preset": "stepper-states",
    "width": 640
  },
  "parts": [
    {
      "id": "steps",
      "kind": "step-rail",
      "presentation": "Use the approved card shell, with story and navigation instructions above the experiment. Keep step labels readable; progress belongs on this rail.",
      "bind": {
        "active": "state.id",
        "items": "variant.states"
      }
    },
    {
      "id": "encryption-picture",
      "kind": "fixed-picture",
      "presentation": "Keep all regions stationary, with readable labels at native width. Highlight only Message; show its contents exclusively in the readout. Reference captures show private-decrypt.",
      "bind": {
        "active": "state.active",
        "links": "variant.links",
        "regions": "variant.regions"
      }
    },
    {
      "id": "message-callout",
      "kind": "active-callout",
      "presentation": "Anchor beside Message without covering labels. Identify the active operation and explain its mechanism; leave message contents in the readout.",
      "bind": {
        "reason": "state.why",
        "target": "state.calloutRegion",
        "text": "state.sentence"
      }
    },
    {
      "id": "message-evidence",
      "kind": "value-readout",
      "presentation": "Show Message contents in one stable location. Render Status as the bound status line beneath it. Preserve identical text for the original and recovered plaintext.",
      "bind": {
        "values": "state.readouts"
      }
    }
  ],
  "controls": [
    {
      "id": "state",
      "kind": "index",
      "label": "Previous / Next",
      "items": "variant.states",
      "presentation": "Previous and Next move one state, defaulting to the first state. Bounds are the first and last states; increment is one. Disable boundary buttons while retaining their names. Every state persists until the learner acts, including private-decrypt. Parameter-control budget: zero; navigation and reset are separate. Provide accessible button names, visible focus, and Enter or Space activation."
    },
    {
      "id": "reset",
      "kind": "reset",
      "label": "Reset",
      "presentation": "Restore the first state and all defaults. Provide visible focus and keyboard activation."
    }
  ],
  "data": {
    "variants": [
      {
        "label": "Public-key encryption",
        "regions": [
          {
            "id": "public-key",
            "label": "Public key",
            "values": [
              "Shared with anyone",
              "Belongs to Receiver"
            ]
          },
          {
            "id": "message",
            "label": "Message",
            "actors": [
              "Sender",
              "Receiver"
            ]
          },
          {
            "id": "private-key",
            "label": "Private key",
            "values": [
              "Kept secret by Receiver",
              "Matches Public key"
            ]
          }
        ],
        "links": [
          {
            "from": "public-key",
            "to": "message",
            "label": "Used for encryption"
          },
          {
            "from": "private-key",
            "to": "message",
            "label": "Used for decryption"
          }
        ],
        "states": [
          {
            "id": "plaintext",
            "label": "Start",
            "short": "Readable message",
            "sentence": "Message starts with Sender.",
            "why": "Receiver creates a matching key pair, shares Public key, and keeps Private key secret.",
            "active": [
              "message"
            ],
            "calloutRegion": "message",
            "readouts": [
              {
                "id": "contents",
                "label": "Message contents",
                "value": "MEET AT NOON"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Plaintext ready for encryption"
              }
            ]
          },
          {
            "id": "public-encrypt",
            "label": "Encrypt",
            "short": "Use Public key",
            "sentence": "Sender encrypts Message with Public key.",
            "why": "Sender needs Receiver’s public key, not Receiver’s private key. The resulting ciphertext can travel over an observable channel.",
            "active": [
              "message"
            ],
            "calloutRegion": "message",
            "readouts": [
              {
                "id": "contents",
                "label": "Message contents",
                "value": "Schematic ciphertext"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Encrypted; original text concealed"
              }
            ]
          },
          {
            "id": "public-attempt",
            "label": "Try Public key",
            "short": "Ciphertext stays concealed",
            "sentence": "Compare decryption using only Public key.",
            "why": "Under our assumptions, Public key and the ciphertext do not provide a feasible way to recover the original message.",
            "active": [
              "message"
            ],
            "calloutRegion": "message",
            "readouts": [
              {
                "id": "contents",
                "label": "Message contents",
                "value": "Schematic ciphertext"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Public key alone cannot feasibly recover plaintext"
              }
            ]
          },
          {
            "id": "private-decrypt",
            "label": "Use Private key",
            "short": "Original message recovered",
            "sentence": "Receiver decrypts Message with Private key.",
            "why": "The matching Private key enables decryption. Sharing Public key did not require sharing the secret needed to recover Message.",
            "active": [
              "message"
            ],
            "calloutRegion": "message",
            "readouts": [
              {
                "id": "contents",
                "label": "Message contents",
                "value": "MEET AT NOON"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Private key recovered the original plaintext"
              }
            ]
          }
        ]
      }
    ]
  }
}
